#nullable enable // autogenerated

using System;
using System.Globalization;
using System.IO;
using System.Linq;
using MVZ2.Managers;
using MVZ2.Sprites;
using MVZ2Logic.Resources;
using Newtonsoft.Json;
using NGettext;
using PVZEngine;
using PVZEngine.Tools.Unity;
using UnityEngine;

namespace MVZ2.Localization
{
    public class ResourcePackReaderDirectoryV1 : ResourcePackReaderV1, IResourcePackReaderDirectory
    {
        public ResourcePackReaderDirectoryV1(MainManager main) : base(main)
        {
        }

        public override ResourcePack? ReadPack(string key, string path)
        {
            try
            {
                // 新建一个资源包实例。
                var pack = new ResourcePack(key);

                // manifest路径。
                var manifestPath = Path.Combine(path, MANIFEST_FILENAME);

                // 将manifest读取到内存。
                var manifest = LoadManifest(manifestPath);
                if (manifest == null)
                {
                    throw new FileNotFoundException($"The file {MANIFEST_FILENAME} in resource pack {path} is missing!");
                }

                // 从manifest中读取资源包内容。
                LoadFromManifest(path, manifest, pack, key);

                return pack;
            }
            catch (Exception e)
            {
                Debug.LogError($"读取语言包{path}失败：{e}");
                return null;
            }
        }
        private ResourcePackManifest? LoadManifest(string path)
        {
            if (!File.Exists(path))
                return null;
            using var manifestStream = File.Open(path, FileMode.Open);
            using var manifestReader = new StreamReader(manifestStream);
            var manifestJson = manifestReader.ReadToEnd();

            return JsonConvert.DeserializeObject<ResourcePackManifest>(manifestJson);
        }
        private void LoadFromManifest(string path, ResourcePackManifest manifest, ResourcePack pack, string key)
        {
            // 加载翻译文件。
            LoadCatalogsFromManifest(path, manifest, pack);

            // 加载贴图。
            LoadSpritesFromManifest(path, manifest, pack, key);
        }
        private void LoadCatalogsFromManifest(string path, ResourcePackManifest manifest, ResourcePack pack)
        {
            if (manifest.localization == null)
                return;

            if (manifest.localization.languages != null)
            {
                foreach (var language in manifest.localization.languages)
                {
                    // 语言代码。
                    var code = language.code;
                    if (string.IsNullOrEmpty(code))
                        continue;

                    if (language.catalogs != null)
                    {
                        foreach (var relativePath in language.catalogs)
                        {
                            // 获取catalog的路径，并加载。
                            var catalogPath = Path.Combine(path, "assets", relativePath);
                            var catalog = LoadPackMOFileDirectory(catalogPath, code);

                            // 将加载后的catalog注册。
                            var packCatalogs = pack.GetOrCreateLanguageCatalogs(code);
                            var filenameWithoutExt = Path.GetFileNameWithoutExtension(catalogPath);
                            packCatalogs.catalogs.Add(filenameWithoutExt, catalog);
                        }
                    }
                }
            }
        }
        private Catalog LoadPackMOFileDirectory(string moFile, string lang)
        {
            using (var stream = File.Open(moFile, FileMode.Open))
            {
                using (MemoryStream memory = new MemoryStream())
                {
                    stream.CopyTo(memory);
                    memory.Seek(0, SeekOrigin.Begin);
                    return new Catalog(memory, new CultureInfo(lang));
                }
            }
        }
        private void LoadSpritesFromManifest(string path, ResourcePackManifest manifest, ResourcePack pack, string key)
        {
            // 加载贴图
            if (manifest.textures != null)
            {
                var generatedCategory = GetLanguagePackSpriteCategory(key);

                foreach (var packTexture in manifest.textures)
                {
                    if (string.IsNullOrEmpty(packTexture.texture))
                        continue;

                    // 获取贴图路径。
                    var texturePath = Path.Combine(path, "assets", packTexture.texture).Replace("\\", "/");

                    // 文件不存在，直接跳过。
                    if (!File.Exists(texturePath))
                        continue;

                    var slices = packTexture.slices;
                    if (slices == null)
                        continue;

                    // 尝试获取资源包中的这个texture对象。
                    // 如果没有获取到，新建一个。
                    if (!pack.textures.TryGetValue(texturePath, out var texture))
                    {
                        texture = ReadTexture2DDirectory(texturePath);
                        pack.textures.Add(texturePath, texture);
                    }

                    // 获取ID和图片标签。
                    var splitTexturePaths = Path.ChangeExtension(packTexture.texture, string.Empty).TrimEnd('.').Split('/', '\\');
                    string nsp, textureId;
                    if (splitTexturePaths.Length > 1)
                    {
                        nsp = splitTexturePaths[0];
                        textureId = string.Join("/", splitTexturePaths.Skip(1));
                    }
                    else
                    {
                        nsp = string.Empty;
                        textureId = string.Join("/", splitTexturePaths);
                    }
                    var splitTagTexturePaths = textureId.Split("@");
                    textureId = splitTagTexturePaths[0];
                    var tags = splitTagTexturePaths.Skip(1).ToArray();

                    // 加载贴图。
                    for (int i = 0; i < slices.Length; i++)
                    {
                        var slice = slices[i];
                        var spriteRef = slice.replaces;
                        if (spriteRef == null)
                        {
                            if (string.IsNullOrEmpty(nsp))
                            {
                                Log.LogWarning($"Cannot load sprite {packTexture.texture} from resource pack: Invalid file path.");
                                continue;
                            }
                            var spriteID = new NamespaceID(nsp, textureId);
                            spriteRef = new SpriteReference(spriteID, i);
                        }
                        var spriteKey = new SpriteLookupKey(spriteRef, tags);
                        var sprite = CreateSprite(texture, slice, spriteKey.ToString(), generatedCategory);
                        pack.AddSprite(spriteKey, sprite);
                    }
                }
            }
        }
        private Texture2D ReadTexture2DDirectory(string texturePath)
        {
            using var spriteStream = File.Open(texturePath, FileMode.Open);
            using var spriteMemory = new MemoryStream();
            spriteStream.CopyTo(spriteMemory);

            var bytes = spriteMemory.ToArray();
            return Main.ResourceManager.GenerateTextureFromBytes(bytes, texturePath);
        }
    }
}
